1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * The single definition of household membership, shared by {@link EnsureUniqueOwnerHousehold}
9	 * (which rejects an unshared duplicate) and {@link AssignOwnerHousehold} (which assigns the
10	 * shared id), so the guard and the assignment agree by construction rather than by comment.
11	 * Two owners are in the same household when their lastName and address match. lastName is
12	 * compared case-insensitively with collapsed whitespace; address is compared using the
13	 * shared {@link AddressNormalizer} form, so the guard and the assignment agree with the
14	 * address that is stored and returned.
15	 */
16	final class OwnerHousehold {
17	
18	    private OwnerHousehold() {
19	    }
20	
21	    /** Whether an owner with the given lastName and address shares a household with {@code other}. */
22	    static boolean isSameHousehold(String lastName, String address, Owner other) {
23	        return normalize(lastName).equals(normalize(other.getLastName()))
24	                && AddressNormalizer.normalize(address).equals(AddressNormalizer.normalize(other.getAddress()));
25	    }
26	
27	    /** Lower-case and collapse whitespace runs to a single space for comparison. */
28	    private static String normalize(String value) {
29	        if (value == null) {
30	            return "";
31	        }
32	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
33	    }
34	}
