1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.UUID;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	
12	/**
13	 * Assigns the owner's {@code householdId} when the request opts in with
14	 * {@code sharesHousehold} true. Housemates — see {@link OwnerHousehold} for the membership
15	 * rule shared with {@link EnsureUniqueOwnerHousehold} — receive one stable shared
16	 * identifier: the first existing housemate's id is reused, otherwise a fresh one is minted
17	 * and back-filled onto every existing housemate so later joiners keep sharing it. Runs after
18	 * the owner is built and before it is saved; leaves {@code householdId} null when
19	 * {@code sharesHousehold} is not true.
20	 */
21	public class AssignOwnerHousehold {
22	
23	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
24	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
25	            return;
26	        }
27	
28	        // One pass: collect the existing housemates and reuse any id they already share.
29	        List<Owner> housemates = new ArrayList<>();
30	        String householdId = null;
31	        for (Owner existing : ownerRepository.findAll()) {
32	            if (OwnerHousehold.isSameHousehold(owner.getLastName(), owner.getAddress(), existing)) {
33	                housemates.add(existing);
34	                if (householdId == null && existing.getHouseholdId() != null) {
35	                    householdId = existing.getHouseholdId();
36	                }
37	            }
38	        }
39	        if (householdId == null) {
40	            householdId = UUID.randomUUID().toString();
41	        }
42	
43	        // Back-fill the shared id onto any housemate that lacks it, so the whole household
44	        // ends up on one identifier and later joiners reuse it.
45	        for (Owner housemate : housemates) {
46	            if (housemate.getHouseholdId() == null) {
47	                housemate.setHouseholdId(householdId);
48	                ownerRepository.save(housemate);
49	            }
50	        }
51	
52	        owner.setHouseholdId(householdId);
53	    }
54	}
