1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * Rejects a create whose lastName and address already belong to an existing owner
11	 * (see {@link OwnerHousehold} for the membership rule). A clash is rejected 409 via
12	 * {@link DuplicateHouseholdException}, unless the request opts in with
13	 * {@code sharesHousehold} true — in which case {@link AssignOwnerHousehold} gives the
14	 * housemates a shared id.
15	 */
16	public class EnsureUniqueOwnerHousehold {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateHouseholdException {
20	        // Opt-in flag lets known housemates share a lastName and address.
21	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
22	            return;
23	        }
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (OwnerHousehold.isSameHousehold(request.getLastName(), request.getAddress(), existing)) {
26	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
27	            }
28	        }
29	    }
30	}
