7	/**
8	 * Assigns the owner's {@code namesakeCount}: the number of existing owners that share
9	 * the same first name and last name (compared case-insensitively). Runs before the
10	 * owner is saved, so the count reflects only the owners that existed before this
11	 * create.
12	 */
13	public class AssignNamesakeCount {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String firstName = owner.getFirstName();
17	        String lastName = owner.getLastName();
18	        int count = 0;
19	        for (Owner existing : ownerRepository.findAll()) {
20	            if (firstName.equalsIgnoreCase(existing.getFirstName())
21	                    && lastName.equalsIgnoreCase(existing.getLastName())) {
22	                count++;
23	            }
24	        }
25	        owner.setNamesakeCount(count);
26	    }
27	}
